 概览 # day1知识点 # c++发展历史 # 诞生的直接原因：Bjarne博士在研究Unix内核时，发现没有合适的工具可以有效的分析由于内核分布而造成的网络流量以及如何将内核模块化 c++应用方向 # 命名空间 # /* // 为了避免不经意间的名称冲突，让重复名称被正确管理，创造了命名空间 正确使用命名空间，我们有三种方法： 1. 将命名空间写完整，处处使用std::cout,std::endl; 2. 靠经验使得不冲突(不可靠) 3. 使用一个写一个命名空间：using std::cout; 命名空间有一些自己的特性： 1. 可以嵌套使用，namespace nice{namespace nice {}} 2. 可以扩展，比如你可以给std空间增加内容而不会报错（但很容易冲突）。为防止报错，一般不扩写。系统命名空间一般都是小写。 3. 就近覆盖 4. 在命名空间中，我们可以定义变量、函数、结构体、命名空间，统称为实体 5. :: 叫做“作用域限定符” */ // 1. 嵌套 namespace test { namespace test { void TestNameSpace(); } } // 2. 追加 namespace std { void MyStdFunc() { std::cout &lt;&lt; &#34;My std Funct&#34; &lt;&lt; std::endl; } } // 3. 就近覆盖 // 全局变量 print int print = 10; namespace OverWrite { int print = 20; void test(int print = 1) { std::cout &lt;&lt; &#34;形式参数 print = &#34; &lt;&lt; print &lt;&lt; std::endl; std::cout &lt;&lt; &#34;命名空间内的 print = &#34; &lt;&lt; OverWrite::print &lt;&lt; std::endl; std::cout &lt;&lt; &#34;全局变量 print = &#34; &lt;&lt; ::print &lt;&lt; std::endl; } } const关键字 # /**** 常量修饰符，这里我们需要区分两个内容**指针常量**和**常量指针** 核心区分方式：从右往左读。 const 修饰的是它左边的内容（如果左边有东西的话），如果左边没有东西，则修饰右边： 1. *常量指针 (pointer to const)*：const int *p 或 int const *p 1. 读法：p 是一个指针，指向 const int 2. 含义：指向的值不能改，指针本身可以改 3. *p = 10; ❌ | p = &amp;b; ✅ 2. *指针常量 (const pointer)*：int * const p 1. 读法：p 是一个 const 指针，指向 int 2. 含义：指针本身不能改，指向的值可以改 3. *p = 10; ✅ | p = &amp;b; ❌ 4. 组合：const int * const p — 都不能改 * 和运算符优先级无关。 区别完全取决于 const 相对于 * 的位置，跟优先级规则没有直接关系。 * 运算符优先级影响的是带解引用的表达式求值顺序（如 *p++ vs (*p)++），而不是类型声明本身的语义。 * 类型声明遵循的是 C/C++ 的&#34;声明模仿使用&#34;（declaration mimics use）语法规则。 &gt; 中文区分：从左往右读 * const : 指针常量 const * : 常量指针 &gt; 英文区分：从右往左读 * const : a const pointer const * : a pointer to const ****/ #include &lt;iostream&gt; using std::cout; using std::endl; //宏定义发生的时机是在预处理阶段,字符串替换,有bug会到运行时才会发现 #define MAX 10 #define multiply(x, y) ((x) * (y)) void test() { //发生时机在编译阶段,会进行类型安全检查,如果有bug在编译时候就会出现 //内置类型：char/short/int/long/double/float/void * const int number = 10;//const修饰的变量称为常量，必须在定义的时候进行初始化 /* number = 20;//赋值,常量不能进行赋值 */ int const number2 = 20; } //函数指针 指针函数 //int (*pf)(int) int* pf(int) // //数组指针 指针数组 //int (*pArray)[] int* pArray[] void test2() { int value = 2; int value1 = 10; int *p1 = &amp;value1; p1 = &amp;value; *p1 = 20000; cout &lt;&lt; endl; int value2 = 200; const int *p2 = &amp;value2;//当const位于*左边的时候，常量指针(pointer to const) /* *p2 = 222;//error,不能修改指针所指变量的值 */ p2 = &amp;value;//ok,可以改变指针本身（指向） cout &lt;&lt; endl; int value3 = 300; int const *p3 = &amp;value3;//当const位于*左边的时候，常量指针(pointer to const) /* *p3 = 333;//error,不能修改指针所指变量的值 */ p3 = &amp;value;//ok,可以改变指针本身（指向） cout &lt;&lt; endl; int value4 = 400; int * const p4 = &amp;value4;//当const位于*右边的时候，指针常量(const pointer) *p4 = 444;//ok,可以修改指针所指变量的值 /* p4 = &amp;value;//error,不可以改变指针本身（指向） */ cout &lt;&lt; endl; int value5 = 500; const int * const p5 = &amp;value5;//双const /* *p5 = 555;//error,不可以修改指针所指变量的值 */ /* p5 = &amp;value;//error,不可以改变指针本身（指向） */ } int main(int argc, char **argv) { test2(); return 0; } new和delete # new/delete与malloc/free的区别是什么?
